    .spark { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; letter-spacing: 1px; }

    .pagination {
      display: flex; justify-content: space-between; align-items: center;
      padding: 12px 14px;
      color: #556070;
      font-size: 13px;
