    .page-btn.active { background: var(--blue); color: #fff; border-color: var(--blue); }

    .summary, .info, footer { padding: 16px; }
    .read-more { color: var(--blue); text-decoration: none; font-weight: 600; cursor: pointer; }
    #more-summary { display: none; margin-top: 10px; color: #445066; }

    .info h3 { margin: 12px 0 6px; }
