  <script>
    const categoryTabs = ["Top", "Trending", "Watchlist", "Prediction Markets", "Most Visited", "New", "More"];
    const networkTabs = ["All Networks", "BSC", "Solana", "Base", "Ethereum", "More"];
    const promos = [
      "CTP Launch: Secure $GENIUS Airdrop — Join Now",
      "Featured Partner: Institutional custody now live",
      "Ecosystem Update: New analytics endpoints available"
    ];

    const baseCoins = [
      {name:"Bitcoin",sym:"BTC",price:75612.78,h1:0.45,h24:1.33,d7:4.84,mcap:"$1.51T",vol:"$42.82B",supply:"20.01M BTC",spark:"▁▂▃▅▆",network:"All Networks"},
      {name:"Ethereum",sym:"ETH",price:2356.00,h1:0.51,h24:0.80,d7:6.29,mcap:"$284.35B",vol:"$21.36B",supply:"120.69M ETH",spark:"▂▃▄▅▆",network:"Ethereum"},
      {name:"Tether",sym:"USDT",price:1.00,h1:0.01,h24:0.03,d7:0.01,mcap:"$185.84B",vol:"$138.79B",supply:"185.8B USDT",spark:"▅▅▅▅▅",network:"Ethereum"},
      {name:"XRP",sym:"XRP",price:1.44,h1:0.71,h24:2.71,d7:7.89,mcap:"$89.13B",vol:"$4.03B",supply:"61.56B XRP",spark:"▂▃▃▅▇",network:"Base"},
      {name:"BNB",sym:"BNB",price:632.59,h1:0.38,h24:1.89,d7:4.98,mcap:"$85.27B",vol:"$1.95B",supply:"134.78M BNB",spark:"▃▃▄▅▆",network:"BSC"},
      {name:"Solana",sym:"SOL",price:88.25,h1:0.67,h24:3.74,d7:5.67,mcap:"$50.77B",vol:"$6.71B",supply:"575.26M SOL",spark:"▂▃▄▅▆",network:"Solana"}
    ];

    const coins = Array.from({length: 8400}, (_, i) => {
      const b = baseCoins[i % baseCoins.length];
      const rank = i + 1;
      const shift = (i % 23) - 11;
      const price = Math.max(0.0001, b.price * (1 + shift / 250));
      const h1 = +(b.h1 + shift / 50).toFixed(2);
      const h24 = +(b.h24 + shift / 20).toFixed(2);
      const d7 = +(b.d7 + shift / 10).toFixed(2);
      return {
        rank,
        name: rank <= 6 ? b.name : `${b.name} ${Math.ceil(rank/6)}`,
        sym: rank <= 6 ? b.sym : `${b.sym}${Math.ceil(rank/6)}`,
        price,
        h1, h24, d7,
        mcap: b.mcap,
        vol: b.vol,
        supply: b.supply,
        spark: b.spark,
        network: b.network,
        category: categoryTabs[rank % categoryTabs.length]
      };
    });

    let selectedCategory = "Top";
    let selectedNetwork = "All Networks";
    let currentPage = 1;
    const perPage = 100;
    let sortBy = "rank";

    const tbody = document.getElementById('tbody');
    const pagesEl = document.getElementById('pages');

    function pctClass(v){ return v >= 0 ? 'up' : 'down'; }
    function fmtPrice(v){ return v >= 1 ? `$${v.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}` : `$${v.toFixed(4)}`; }

    function filtered(){
      return coins.filter(c =>
        (selectedCategory === 'Top' || c.category === selectedCategory) &&
        (selectedNetwork === 'All Networks' || selectedNetwork === 'More' || c.network === selectedNetwork) &&
        (!document.getElementById('only-positive').checked || c.h24 > 0)
      );
    }

    function sortedRows(arr){
      if (sortBy === 'volume') return [...arr].sort((a,b)=> b.vol.localeCompare(a.vol));
      if (sortBy === 'marketcap') return [...arr].sort((a,b)=> b.mcap.localeCompare(a.mcap));
      return [...arr].sort((a,b)=> a.rank-b.rank);
    }

    function renderTable(){
      const rows = sortedRows(filtered());
      const start = (currentPage-1)*perPage;
      const page = rows.slice(start,start+perPage);
      tbody.innerHTML = page.map(c => `
        <tr>
          <td class="num">${c.rank}</td>
          <td><div class="name-cell"><span class="coin-icon">${c.sym.slice(0,2)}</span><span><strong>${c.name}</strong> <span class="sym">${c.sym}</span></span></div></td>
          <td class="num">${fmtPrice(c.price)}</td>
          <td class="num ${pctClass(c.h1)}">${c.h1>=0?'+':''}${c.h1.toFixed(2)}%</td>
          <td class="num ${pctClass(c.h24)}">${c.h24>=0?'+':''}${c.h24.toFixed(2)}%</td>
          <td class="num ${pctClass(c.d7)}">${c.d7>=0?'+':''}${c.d7.toFixed(2)}%</td>
          <td class="num">${c.mcap}</td>
          <td class="num col-vol">${c.vol}</td>
          <td class="num col-supply">${c.supply}</td>
          <td class="num col-spark spark ${pctClass(c.d7)}">${c.spark}</td>
        </tr>
      `).join('');

      const total = rows.length;
      document.getElementById('count-text').textContent = `Showing ${Math.min(start+1,total)}–${Math.min(start+perPage,total)} of ${total.toLocaleString()} assets`;
      renderPages(Math.max(1,Math.ceil(total/perPage)));
    }

    function renderPages(totalPages){
      const pageNumbers = [1,2,3,4,totalPages].filter((v,i,a)=>a.indexOf(v)===i).filter(v=>v<=totalPages);
      pagesEl.innerHTML = '';
      pageNumbers.forEach((p, idx)=>{
        if (idx===4 && totalPages>5) pagesEl.insertAdjacentHTML('beforeend','<span>...</span>');
        const b = document.createElement('button');
        b.className = 'page-btn' + (p===currentPage ? ' active':'');
        b.textContent = p;
        b.onclick = ()=>{ currentPage = p; renderTable(); };
        pagesEl.appendChild(b);
      });
    }

    function renderTabs(target, tabs, selected, cb){
      target.innerHTML = '';
      tabs.forEach(tab => {
        const btn = document.createElement('button');
        btn.className = 'tab' + (tab===selected?' active':'');
        btn.textContent = tab;
        btn.onclick = ()=> cb(tab);
        target.appendChild(btn);
      });
    }

    function syncColumns(){
      document.querySelectorAll('[data-col]').forEach(chk=>{
        const on = chk.checked;
        document.querySelectorAll('.col-'+chk.dataset.col).forEach(el=> el.style.display = on ? '' : 'none');
      });
    }

    renderTabs(document.getElementById('category-tabs'), categoryTabs, selectedCategory, (tab)=>{
      selectedCategory = tab; currentPage = 1;
      renderTabs(document.getElementById('category-tabs'), categoryTabs, selectedCategory, arguments.callee);
      renderTable();
    });

    renderTabs(document.getElementById('network-tabs'), networkTabs, selectedNetwork, (tab)=>{
      selectedNetwork = tab; currentPage = 1;
      renderTabs(document.getElementById('network-tabs'), networkTabs, selectedNetwork, arguments.callee);
      renderTable();
    });

    document.getElementById('toggle-filters').onclick = ()=> document.getElementById('filters-panel').classList.toggle('open');
    document.getElementById('toggle-columns').onclick = ()=> document.getElementById('columns-panel').classList.toggle('open');
    document.getElementById('only-positive').onchange = ()=>{ currentPage = 1; renderTable(); };
    document.querySelectorAll('[data-col]').forEach(chk=> chk.onchange = syncColumns);

    document.getElementById('sort-marketcap').onclick = ()=>{ sortBy = 'marketcap'; renderTable(); };
    document.getElementById('sort-volume').onclick = ()=>{ sortBy = 'volume'; renderTable(); };

    document.getElementById('read-more').onclick = ()=>{
      const more = document.getElementById('more-summary');
      const open = more.style.display === 'block';
      more.style.display = open ? 'none' : 'block';
      document.getElementById('read-more').textContent = open ? 'Read More' : 'Read Less';
    };

    let promoIdx = 0;
    const promoText = document.getElementById('promo-text');
    const setPromo = ()=> promoText.textContent = promos[promoIdx];
    document.getElementById('promo-prev').onclick = ()=>{ promoIdx = (promoIdx - 1 + promos.length) % promos.length; setPromo(); };
    document.getElementById('promo-next').onclick = ()=>{ promoIdx = (promoIdx + 1) % promos.length; setPromo(); };
    setInterval(()=>{ promoIdx = (promoIdx + 1) % promos.length; setPromo(); }, 4000);

    renderTable();
    syncColumns();
  </script>
</body>
